/* شكد ياخذ الطلب من المخزن: العلب المنفردة + الي داخل البوكس */
function boxIncCounts(){
  const r={mabooj:0,torshi:0,rice:0,tamur:0};
  String(settings.boxInc||'').split(/[،,+]/).forEach(p=>{
    const m=p.match(/[×xX*]\s*(\d+)/), n=m?+m[1]:1, t=p.replace(/[×xX*]\s*\d+/,'');
    if(/معبوج/.test(t)) r.mabooj+=n; else if(/طرشي/.test(t)) r.torshi+=n;
    else if(/تمن|رز/.test(t)) r.rice+=n; else if(/تمر/.test(t)) r.tamur+=n;
  });
  return r;
}
function orderStock(o){
  const s={mabooj:0,torshi:0,rice:0,tamur:0,fishbox:0,stubs:0}, inc=boxIncCounts();
  (o.items||[]).forEach(i=>{
    const q=+i.qty||0, n=i.name||'';
    if(n==='علبة معبوج') s.mabooj+=q; else if(n==='علبة طرشي') s.torshi+=q; else if(n==='علبة تمن') s.rice+=q; else if(n==='علبة تمر') s.tamur+=q;
    else if(n.indexOf('سمج مسكوف')===0||(n.includes('بوكس')&&!n.includes('بدون'))){
      s.fishbox+=q; s.stubs+=q;
      Object.keys(inc).forEach(k=>{ s[k]+=inc[k]*q });
    }
  });
  return s;
}
function stockApply(s,sign){
  if(!s) return;
  const add=(o,f,v)=>{ if(v) o[f]=Math.max(0,(o[f]||0)+sign*v) };
  add(settings.mabooj,'sold',s.mabooj); add(settings.torshi,'sold',s.torshi);
  add(settings.rice,'sold',s.rice); add(settings.tamur,'sold',s.tamur);
  add(settings.fishbox,'used',s.fishbox); add(settings.stubs,'used',s.stubs);
}
